class Device {
  constructor(name) {
    this.name = name;
    this.isPoweredOn = false;
  }

  powerOn() {
    this.isPoweredOn = true;
    return `${this.name} is now ON.`;
  }

  powerOff() {
    this.isPoweredOn = false;
    return `${this.name} is now OFF.`;
  }

  getStatus() {
    return `${this.name} is ${this.isPoweredOn ? 'powered on' : 'powered off'}.`;
  }
}

class Smartwatch extends Device {
  constructor(name, brand) {
    super(name);
    this.brand = brand;
  }

  displayTime() {
    if (this.isPoweredOn) {
      return `Displaying time on ${this.name} Smartwatch.`;
    }
    return "Cannot display time. Device is powered off.";
  }

  trackActivity(steps) {
    if (this.isPoweredOn) {
      return `Tracking ${steps} steps on ${this.name} Smartwatch.`;
    }
    return "Cannot track activity. Device is powered off.";
  }

  getStatus() {
    return `${this.name} (${this.brand}) is ${this.isPoweredOn ? 'powered on' : 'powered off'}.`;
  }
}

